param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
$core=Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict'
$source=[IO.File]::ReadAllText((Join-Path $core 'Forces/AICF_AIQuotaLogisticsCreationGuard.c'))
$actual=$source.Replace('protected ref ','public ').Replace('protected ','public ').Replace('ref ','').Replace('override bool','public override bool').Replace('static AICF_AIQuotaLogisticsCreationGuard Capture','public static AICF_AIQuotaLogisticsCreationGuard Capture').Replace('class AICF_AIQuotaLogisticsCreationGuard','public class AICF_AIQuotaLogisticsCreationGuard').Replace('ResourceName','string').Replace('System.GetTickCount()','Clock.Now').Replace('int.MAX','int.MaxValue')
$actual=[regex]::Replace($actual,'(?m)^\t(bool|void) (\w+)\(',' public $1 $2(')
$actual=[regex]::Replace($actual,'vector (\w+)\[4\];','V[] $1=new V[4];')
$actual=$actual.Replace('for (int index;','for (int index=0;')
$adapters=@'
using System;
using System.Collections.Generic;
public static class Strings {public static bool IsEmpty(this string s){return string.IsNullOrEmpty(s);}}
public class N {public static implicit operator bool(N n){return n!=null;}}
public struct V {public int X;public static bool operator==(V a,V b){return a.X==b.X;}public static bool operator!=(V a,V b){return a.X!=b.X;}public override bool Equals(object o){return o is V&&this==(V)o;}public override int GetHashCode(){return X;}}
public static class Clock {public static int Now;}
public enum AICF_EAIQuotaBucket {STOCK,COMBAT}
public enum AICF_EAIQuotaGroupOwner {LOGISTICS,BUILDER}
public enum AICF_ELogisticsPhase {IDLE_AT_DEPOT,SPAWN_PENDING,RETIRING}
public class Entity:N {public int Id;public bool Current=true;public V Position;public V GetOrigin(){return Position;}public int GetID(){return Id;}}
public class SCR_CampaignFaction:N {public string Key="US";public string GetFactionKey(){return Key;}}
public class SCR_CampaignMilitaryBaseComponent:N {public Entity Owner;public Entity GetOwner(){return Owner;}}
public class SCR_EntityCatalogEntry:N {public string Prefab="vehicle.et";public string GetPrefab(){return Prefab;}}
public class SCR_EntitySpawnerSlotComponent:N {public Entity Owner;public Entity GetOwner(){return Owner;}}
public class SCR_CatalogEntitySpawnerComponent:N {public Entity Owner;public bool Allows=true;public Entity GetOwner(){return Owner;}public bool AICF_AllowsLogisticsEntry(SCR_EntityCatalogEntry e,SCR_EntitySpawnerSlotComponent s){return Allows;}}
public class AICF_AIQuotaCatalogIdentity:N {public Entity m_Entity;public int m_Id;public static AICF_AIQuotaCatalogIdentity Capture(Entity e,bool master){return e==null?null:new AICF_AIQuotaCatalogIdentity{m_Entity=e,m_Id=e.Id};}public bool IsCurrent(){return m_Entity&&m_Entity.Current&&m_Entity.Id==m_Id;}}
public class AICF_VehicleSpawnSiteReservation:N {public bool Expired;public bool IsExpired(int now){return Expired;}}
public class AICF_VehicleLease:N {public int Slot,Generation;public bool Registered=true;public bool MatchesTripIdentity(string f,int s,int g,int t){return f=="US"&&Slot==s&&Generation==g&&g==t;}}
public class AICF_FactionFleet:N {public bool OwnsVehicleLease(AICF_VehicleLease l){return l&&l.Registered;}}
public class SCR_AIGroup:N {}
public class AICF_AIQuotaVehicleEntity:N {public Entity m_Entity;public bool IsCurrent(){return m_Entity&&m_Entity.Current;}}
public class AICF_LogisticsWorker:N {public AICF_AIQuotaLogisticsCreationGuard m_QuotaCreationGuard;public bool m_bStopped,m_bQuotaSpawnClosed,m_bCleanupQueued;public int m_iSlot=100,m_iOrdinal=1,m_iGeneration,m_iPhaseAtMs;public SCR_CampaignFaction m_Faction=new SCR_CampaignFaction();public Entity m_Depot;public int m_DepotId,m_HomeId,m_SpawnSlotId;public SCR_CampaignMilitaryBaseComponent m_Home;public SCR_CatalogEntitySpawnerComponent m_Production;public SCR_EntityCatalogEntry m_Entry=new SCR_EntityCatalogEntry();public AICF_VehicleLease m_Lease;public AICF_FactionFleet m_Fleet;public SCR_AIGroup m_Group;public Entity m_Vehicle,m_Driver;public AICF_ELogisticsPhase m_ePhase;public AICF_VehicleSpawnSiteReservation m_Site;public SCR_EntitySpawnerSlotComponent m_SpawnSlot;public V[] m_aSpawnTransform=new V[4],m_aSlotTransform=new V[4];}
public class AICF_LogisticsDepotRegistry {public static bool LiveValue=true;public static bool Live(AICF_LogisticsWorker w){return LiveValue;}}
public class AICF_MatchController:N {public AICF_LogisticsWorker Worker;public bool Current=true;public bool OwnsAIQuotaLogisticsWorker(AICF_LogisticsWorker w){return Current&&Worker==w;}}
public class AICF_AIQuotaGroupOwner:N {public AICF_EAIQuotaGroupOwner m_Kind=AICF_EAIQuotaGroupOwner.LOGISTICS;public AICF_LogisticsWorker m_Logistics;public int m_iGeneration;public SCR_AIGroup m_Group;public bool Current=true;public bool CanDispatch(){return Current;}public bool MatchesIdentity(){return Current;}}
public class Registry:N {public AICF_AIQuotaGroupOwner Owner;public AICF_AIQuotaGroupOwner Find(SCR_AIGroup g){return Owner&&Owner.m_Group==g?Owner:null;}}
public class AICF_AIWorldQuotaService:N {public AICF_MatchController Controller=new AICF_MatchController();public int Available=2,Reserved,ReserveCalls,CancelledGroups;public Action AfterReserve;public Registry Owners=new Registry();public Registry GetOwners(){return Owners;}public void CancelGroupRequest(SCR_AIGroup g){CancelledGroups++;}}
public class AICF_AIQuotaVehicleCreationGuard:N {public AICF_AIWorldQuotaService m_Service;public AICF_MatchController m_Controller;public AICF_AIQuotaVehicleEntity m_Newborn;public bool Bound,Cancelled,Adopted;public AICF_VehicleLease Lease;public virtual bool IsDomainCurrent(){return false;}public bool IsCurrent(){return !Cancelled&&!Bound&&IsDomainCurrent();}public bool Initialize(AICF_AIWorldQuotaService s,AICF_EAIQuotaBucket bucket,int units,string faction,Entity owner,bool master=true){m_Service=s;m_Controller=s.Controller;if(bucket!=AICF_EAIQuotaBucket.COMBAT||!IsCurrent())return false;s.ReserveCalls++;if(s.Available<units)return false;s.Reserved=units;if(s.AfterReserve!=null)s.AfterReserve();return IsCurrent();}public bool AttachPendingLease(AICF_FactionFleet f,AICF_VehicleLease l){if(!IsCurrent())return false;Lease=l;return true;}public bool AdoptRemainingGroup(SCR_AIGroup g,AICF_AIQuotaGroupOwner o){if(!Bound||Cancelled||Adopted||!o.CanDispatch())return false;Adopted=true;return true;}public void CancelAvailable(){Cancelled=true;if(!Adopted&&m_Service)m_Service.Reserved=0;}}
__SOURCE__
public static class Run {
 public static AICF_LogisticsWorker W;public static AICF_FactionFleet Fleet;public static AICF_AIWorldQuotaService S;public static int Cases;
 public static void Need(bool ok,string why){Cases++;if(!ok)throw new Exception(why);}
 public static void Fresh(){Clock.Now=10;AICF_LogisticsDepotRegistry.LiveValue=true;W=new AICF_LogisticsWorker{m_Depot=new Entity{Id=1},m_DepotId=1,m_Home=new SCR_CampaignMilitaryBaseComponent{Owner=new Entity{Id=2}},m_HomeId=2,m_Production=new SCR_CatalogEntitySpawnerComponent{Owner=new Entity{Id=3}}};Fleet=new AICF_FactionFleet();S=new AICF_AIWorldQuotaService();S.Controller.Worker=W;}
 public static AICF_AIQuotaLogisticsCreationGuard Capture(){return AICF_AIQuotaLogisticsCreationGuard.Capture(S,W,Fleet);}
 public static AICF_AIQuotaLogisticsCreationGuard Pending(){var g=Capture();W.m_iGeneration++;if(!g.AcceptGenerationAdvance())throw new Exception("generation setup");W.m_Lease=new AICF_VehicleLease{Slot=W.m_iSlot,Generation=W.m_iGeneration};W.m_Fleet=Fleet;if(!g.AcceptPendingLease(W.m_Lease))throw new Exception("lease setup");W.m_ePhase=AICF_ELogisticsPhase.SPAWN_PENDING;W.m_iPhaseAtMs=10;if(!g.AcceptSpawnPhase())throw new Exception("phase setup");return g;}
 public static int Execute(){Cases=0;Fresh();S.Available=1;Need(Capture()==null&&W.m_iGeneration==0&&W.m_Lease==null&&S.Reserved==0,"full two required before generation or lease");Fresh();var g=Capture();Need(g!=null&&S.Reserved==2&&W.m_iGeneration==0&&W.m_Lease==null,"reserve two before advancing");Need(!g.AcceptGenerationAdvance(),"no predicted generation acceptance");W.m_iGeneration=2;Need(!g.AcceptGenerationAdvance(),"skip generation veto");W.m_iGeneration=1;Need(g.AcceptGenerationAdvance(),"actual one advance accepted");Need(!g.AcceptGenerationAdvance(),"duplicate generation acceptance veto");W.m_Lease=new AICF_VehicleLease{Slot=999,Generation=1};W.m_Fleet=Fleet;Need(!g.AcceptPendingLease(W.m_Lease),"foreign lease slot veto");W.m_Lease=new AICF_VehicleLease{Slot=W.m_iSlot,Generation=1};Need(g.AcceptPendingLease(W.m_Lease),"exact actual pending lease accepted");Need(!g.AcceptPendingLease(W.m_Lease),"duplicate lease capture veto");Need(!g.AcceptSpawnPhase(),"phase must actually transition first");W.m_ePhase=AICF_ELogisticsPhase.SPAWN_PENDING;W.m_iPhaseAtMs=10;Need(g.AcceptSpawnPhase(),"actual phase accepted");Need(!g.AcceptSpawnPhase(),"phase latch one use");Need(g.IsCurrent(),"new pending context current");W.m_iGeneration++;Need(!g.IsCurrent(),"later generation invalidates");
 foreach(string change in new[]{"worker","slot","ordinal","faction","depot","home","production","entry","prefab","stopped","closed","phase","phaseAt","lease","fleet","group","driver","foreignVehicle","depotLost"}){Fresh();g=Pending();switch(change){case"worker":S.Controller.Worker=new AICF_LogisticsWorker();break;case"slot":W.m_iSlot++;break;case"ordinal":W.m_iOrdinal++;break;case"faction":W.m_Faction=new SCR_CampaignFaction();break;case"depot":W.m_Depot=new Entity{Id=1};break;case"home":W.m_Home=new SCR_CampaignMilitaryBaseComponent();break;case"production":W.m_Production=new SCR_CatalogEntitySpawnerComponent();break;case"entry":W.m_Entry=new SCR_EntityCatalogEntry();break;case"prefab":W.m_Entry.Prefab="other.et";break;case"stopped":W.m_bStopped=true;break;case"closed":W.m_bQuotaSpawnClosed=true;break;case"phase":W.m_ePhase=AICF_ELogisticsPhase.RETIRING;break;case"phaseAt":W.m_iPhaseAtMs++;break;case"lease":W.m_Lease=new AICF_VehicleLease();break;case"fleet":W.m_Fleet=new AICF_FactionFleet();break;case"group":W.m_Group=new SCR_AIGroup();break;case"driver":W.m_Driver=new Entity();break;case"foreignVehicle":W.m_Vehicle=new Entity();break;case"depotLost":AICF_LogisticsDepotRegistry.LiveValue=false;break;}Need(!g.IsCurrent(),"exact identity "+change);}
 Fresh();g=Pending();W.m_Site=new AICF_VehicleSpawnSiteReservation();W.m_SpawnSlot=new SCR_EntitySpawnerSlotComponent{Owner=new Entity{Id=4}};W.m_SpawnSlotId=4;Need(g.CaptureSite(),"actual site capture");Need(!g.CaptureSite(),"one site capture only");W.m_Site.Expired=true;Need(!g.IsCurrent(),"expired site veto");W.m_Site.Expired=false;W.m_aSpawnTransform[1]=new V{X=9};Need(!g.IsCurrent(),"spawn transform mutation veto");W.m_aSpawnTransform[1]=new V();W.m_SpawnSlot.Owner.Position=new V{X=9};Need(!g.IsCurrent(),"actual slot motion veto");W.m_SpawnSlot.Owner.Position=new V();Need(g.IsCurrent(),"restored same local scope readback");g.Bound=true;W.m_Group=new SCR_AIGroup();var owner=new AICF_AIQuotaGroupOwner{m_Logistics=W,m_iGeneration=W.m_iGeneration,m_Group=W.m_Group};Need(g.AdoptDriver(W.m_Group,owner),"remaining driver adopted after actual vehicle bind");S.Owners.Owner=owner;W.m_bQuotaSpawnClosed=true;g.CloseSpawn();Need(S.CancelledGroups==1&&S.Reserved==2,"close cancels exact adopted group while bound body receipt retained");Fresh();g=Pending();g.Bound=true;W.m_Group=new SCR_AIGroup();owner=new AICF_AIQuotaGroupOwner{m_Logistics=W,m_iGeneration=W.m_iGeneration,m_Group=W.m_Group};Need(g.AdoptDriver(W.m_Group,owner),"second close setup");S.Owners.Owner=new AICF_AIQuotaGroupOwner{m_Group=W.m_Group};W.m_bQuotaSpawnClosed=true;g.CloseSpawn();Need(S.CancelledGroups==0,"successor owner reservation never cancelled");Fresh();var successor=new AICF_AIQuotaLogisticsCreationGuard();S.AfterReserve=()=>W.m_QuotaCreationGuard=successor;Need(Capture()==null&&W.m_QuotaCreationGuard==successor&&S.Reserved==0,"reserve reentry preserves successor pointer and refunds only failed basket");return Cases;}
}
'@
function Compile-Guard([string]$text){$ns='LogisticsQuota'+[guid]::NewGuid().ToString('N');$body=$adapters.Replace('__SOURCE__',$text);Add-Type ('namespace '+$ns+' {'+$body+'}');return [type]($ns+'.Run')}
$type=Compile-Guard $actual;$cases=$type.GetMethod('Execute').Invoke($null,@())
$unsafe=0
foreach($mutation in @(
 @('partial basket','AICF_EAIQuotaBucket.COMBAT, 2,','AICF_EAIQuotaBucket.COMBAT, 1,'),
 @('generation prediction','m_Worker.m_iGeneration != m_iGeneration + 1','m_Worker.m_iGeneration < m_iGeneration + 1'),
 @('phase identity','m_Worker.m_iPhaseAtMs != m_iSpawnPhaseAt','false'),
 @('successor cleanup','m_Service.GetOwners().Find(m_DriverOwner.m_Group) == m_DriverOwner','true'),
 @('worker successor pointer','m_Worker.m_QuotaCreationGuard != this','false')
)){
 if(!$actual.Contains($mutation[1])){throw "Missing actual guard mutant $($mutation[0])"}
 $mutant=Compile-Guard ($actual.Replace($mutation[1],$mutation[2]));$rejected=$false;try{$null=$mutant.GetMethod('Execute').Invoke($null,@())}catch{$rejected=$true}
 if(!$rejected){throw "Unsafe logistics guard survived $($mutation[0])"};$unsafe++
}
"PASS logistics vehicle quota actual_guard_cases=$cases executed_unsafe=$unsafe common_factory_native=NOT_RUN"
